#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_TENANTS 64
#define KEY_SIZE 32
#define NONCE_SIZE 12
#define TAG_SIZE 16
#define MSG_MAX 4096

typedef struct {
    uint8_t key[KEY_SIZE];
    uint32_t tenant_id;
    uint64_t msg_counter;
    int active;
} tenant_ctx_t;

typedef struct {
    uint32_t tenant_id;
    uint8_t nonce[NONCE_SIZE];
    uint8_t ciphertext[MSG_MAX];
    uint8_t tag[TAG_SIZE];
    uint32_t ct_len;
} encrypted_msg_t;

static tenant_ctx_t tenants[MAX_TENANTS];
static pthread_mutex_t tenant_lock = PTHREAD_MUTEX_INITIALIZER;

/* Simplified ChaCha20-Poly1305 stub for demonstration */
static int aead_decrypt(const uint8_t *key, const uint8_t *nonce,
                        const uint8_t *ct, uint32_t ct_len,
                        const uint8_t *tag, uint8_t *pt) {
    /* In production this would be a real AEAD cipher */
    for (uint32_t i = 0; i < ct_len; i++)
        pt[i] = ct[i] ^ key[i % KEY_SIZE] ^ nonce[i % NONCE_SIZE];
    return 0; /* assume tag valid */
}

static void derive_nonce(uint64_t counter, uint32_t tenant_id, uint8_t *nonce) {
    memset(nonce, 0, NONCE_SIZE);
    memcpy(nonce, &counter, sizeof(counter));
    memcpy(nonce + 8, &tenant_id, sizeof(tenant_id));
}

static tenant_ctx_t *find_tenant(uint32_t tenant_id) {
    for (int i = 0; i < MAX_TENANTS; i++) {
        if (tenants[i].active && tenants[i].tenant_id == tenant_id)
            return &tenants[i];
    }
    return NULL;
}

int register_tenant(uint32_t tenant_id, const uint8_t *master_secret) {
    if (!master_secret) return -1;
    pthread_mutex_lock(&tenant_lock);
    /* Reject duplicate registration to prevent counter reset / nonce reuse */
    if (find_tenant(tenant_id) != NULL) {
        pthread_mutex_unlock(&tenant_lock);
        return -1;
    }
    for (int i = 0; i < MAX_TENANTS; i++) {
        if (!tenants[i].active) {
            tenants[i].tenant_id = tenant_id;
            tenants[i].msg_counter = 0;
            tenants[i].active = 1;
            /* Derive per-tenant key from master secret and tenant_id */
            memcpy(tenants[i].key, master_secret, KEY_SIZE);
            /* XOR tenant_id into first 4 bytes for differentiation */
            uint32_t tid_net = tenant_id;
            tenants[i].key[0] ^= (tid_net >> 24) & 0xFF;
            tenants[i].key[1] ^= (tid_net >> 16) & 0xFF;
            tenants[i].key[2] ^= (tid_net >> 8) & 0xFF;
            tenants[i].key[3] ^= tid_net & 0xFF;
            pthread_mutex_unlock(&tenant_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&tenant_lock);
    return -1;
}

int deregister_tenant(uint32_t tenant_id) {
    pthread_mutex_lock(&tenant_lock);
    tenant_ctx_t *ctx = find_tenant(tenant_id);
    if (ctx) {
        memset(ctx->key, 0, KEY_SIZE);
        ctx->active = 0;
        pthread_mutex_unlock(&tenant_lock);
        return 0;
    }
    pthread_mutex_unlock(&tenant_lock);
    return -1;
}

int process_message(const encrypted_msg_t *msg, uint8_t *plaintext, uint32_t *pt_len) {
    if (!msg || !plaintext || !pt_len) return -1;
    if (msg->ct_len > MSG_MAX) return -1;

    pthread_mutex_lock(&tenant_lock);
    tenant_ctx_t *ctx = find_tenant(msg->tenant_id);
    if (!ctx) {
        pthread_mutex_unlock(&tenant_lock);
        return -1;
    }

    /* Derive expected nonce from internal counter - reject replayed nonces */
    uint8_t expected_nonce[NONCE_SIZE];
    derive_nonce(ctx->msg_counter, msg->tenant_id, expected_nonce);

    if (memcmp(expected_nonce, msg->nonce, NONCE_SIZE) != 0) {
        pthread_mutex_unlock(&tenant_lock);
        return -1;
    }

    int ret = aead_decrypt(ctx->key, expected_nonce, msg->ciphertext,
                           msg->ct_len, msg->tag, plaintext);
    if (ret == 0) {
        *pt_len = msg->ct_len;
        ctx->msg_counter++;
    }
    pthread_mutex_unlock(&tenant_lock);
    return ret;
}

int send_encrypted(uint32_t tenant_id, const uint8_t *plaintext,
                   uint32_t pt_len, encrypted_msg_t *out) {
    if (!plaintext || !out || pt_len > MSG_MAX) return -1;

    pthread_mutex_lock(&tenant_lock);
    tenant_ctx_t *ctx = find_tenant(tenant_id);
    if (!ctx) {
        pthread_mutex_unlock(&tenant_lock);
        return -1;
    }

    out->tenant_id = tenant_id;
    out->ct_len = pt_len;
    derive_nonce(ctx->msg_counter, tenant_id, out->nonce);

    for (uint32_t i = 0; i < pt_len; i++)
        out->ciphertext[i] = plaintext[i] ^ ctx->key[i % KEY_SIZE] ^ out->nonce[i % NONCE_SIZE];

    memset(out->tag, 0xAA, TAG_SIZE);
    ctx->msg_counter++;
    pthread_mutex_unlock(&tenant_lock);
    return 0;
}
